 return ans.numerator

TRI=(3,[(0,0,1),(1,1,3),(2,1,3)],1)
C4=(4,[(0,0,1),(1,1,4),(2,1,4),(2,2,2),(3,1,4)],1)
P3=(3,[(0,0,1),(1,1,2),(2,1,1)],0)

def brute(n,edges):
