def embedG(H):
 n=len(H);s=n+9;xs=[z3.Int('x'+str(i)) for i in range(n)];sol=z3.Solver();sol.set(timeout=3000);sol.add(z3.Distinct(xs));sol.add(*[z3.And(x>=0,x<2*s) for x in xs])
 for u,v in H.edges:
